// Lab 23.1, provided (CUDA; also built for HIP and for the CPU emulator).
// The driver's instruments. Not in the book; you do not edit this file.
//
//  - probeEngines: asyncEngineCount and concurrentKernels. NVIDIA documents
//    asyncEngineCount as the number of copy engines: with one, a host-to-device
//    and a device-to-host copy cannot run at the same time; with two they can
//    (notes/today/ch23-facts.md A7). On ROCm the field is the runtime constant 8
//    on every device and counts no hardware (B3). The emulator's device
//    properties have neither field, so it answers -1.
//  - pinnedAlloc: page-locked host memory, the kind the book says an async copy
//    needs (pp. 562-563; A6 for what happens without it).
//  - probeCopyIn, probeKernel, probeCopyOut: the three parts of the round trip,
//    each over the whole array in the default stream, timed with events (ch02
//    A5). The driver uses them to pick the kernel's degree and prints them.
#include <cstdio>

#include "overlap.h"

#define PROBE_CHECK(call)                                                \
    do {                                                                 \
        cudaError_t err = (call);                                        \
        if (err != cudaSuccess) {                                        \
            printf("%s in %s at line %d\n", cudaGetErrorString(err),     \
                   __FILE__, __LINE__);                                  \
            return 1;                                                    \
        }                                                                \
    } while (0)

void probeEngines(int* asyncEngines, int* concurrentKernels) {
    *asyncEngines = *concurrentKernels = -1;
#if defined(PMPP_EMU) || defined(PMPP_CUDA_FRONTEND_CHECK)
    // Neither the emulator nor the front-end check's stub declares the fields.
#else
    // Same field names on HIP (hipDeviceProp_t, ch23-facts B3). Unverified on HIP:
    // not compiled against ROCm here.
    cudaDeviceProp p;
    if (cudaGetDeviceProperties(&p, 0) == cudaSuccess) {
        *asyncEngines = p.asyncEngineCount;
        *concurrentKernels = p.concurrentKernels;
    }
#endif
}

float* pinnedAlloc(size_t floats) {
    float* p = nullptr;
    cudaError_t err = cudaMallocHost((void**)&p, floats * sizeof(float));
    if (err != cudaSuccess) {
        printf("cudaMallocHost of %zu bytes: %s\n", floats * sizeof(float), cudaGetErrorString(err));
        return nullptr;
    }
    return p;
}
void pinnedFree(float* p) {
    if (p) cudaFreeHost(p);
}

// 0: copy in, 1: kernel, 2: copy out.
static int timePart(const StagedJob& job, int part, int degree, int reps, double* seconds) {
    const size_t bytes = (size_t)job.n * sizeof(float);
    cudaEvent_t start, stop;
    PROBE_CHECK(cudaEventCreate(&start));
    PROBE_CHECK(cudaEventCreate(&stop));
    float best = 1e30f;
    for (int r = 0; r <= reps; ++r) {   // r == 0 is an untimed warm-up
        PROBE_CHECK(cudaDeviceSynchronize());
        PROBE_CHECK(cudaEventRecord(start));
        if (part == 0) {
            PROBE_CHECK(cudaMemcpy(job.d_in, job.hostIn, bytes, cudaMemcpyHostToDevice));
        } else if (part == 1) {
            if (launchPoly(job.d_in, job.d_out, job.n, degree, 0) != 0) return 1;
            PROBE_CHECK(cudaGetLastError());
        } else {
            PROBE_CHECK(cudaMemcpy(job.hostOut, job.d_out, bytes, cudaMemcpyDeviceToHost));
        }
        PROBE_CHECK(cudaEventRecord(stop));
        PROBE_CHECK(cudaEventSynchronize(stop));
        float ms = 0;
        PROBE_CHECK(cudaEventElapsedTime(&ms, start, stop));
        if (r > 0 && ms < best) best = ms;
    }
    PROBE_CHECK(cudaEventDestroy(start));
    PROBE_CHECK(cudaEventDestroy(stop));
    *seconds = best * 1e-3;
    return 0;
}

int probeCopyIn(const StagedJob& job, int reps, double* seconds) { return timePart(job, 0, 0, reps, seconds); }
int probeKernel(const StagedJob& job, int degree, int reps, double* seconds) { return timePart(job, 1, degree, reps, seconds); }
int probeCopyOut(const StagedJob& job, int reps, double* seconds) { return timePart(job, 2, 0, reps, seconds); }
